SELECT 'sec' AS kind, sp AS k1, n_other AS k2, count(*) AS n FROM (SELECT p.mention_notice_id AS nid, p.mention_section_id AS sid, max(CASE WHEN p.role = 'Procedure-SProvider' THEN 1 ELSE 0 END) AS sp, count(DISTINCT CASE WHEN p.role <> 'Procedure-SProvider' THEN p.role END) AS n_other FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 2997642 AND p.seq = t.current_seq GROUP BY p.mention_notice_id, p.mention_section_id) s GROUP BY sp, n_other UNION ALL SELECT 'buyer' AS kind, b.organization_id AS k1, o.name AS k2, count(DISTINCT q.tid) AS n FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 2997642 AND p.seq = t.current_seq AND p.role = 'Procedure-SProvider') q CROSS JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.role IN ('Procedure-Buyer', 'buyer') CROSS JOIN organizations o ON o.id = b.organization_id GROUP BY b.organization_id, o.name ORDER BY kind, n DESC LIMIT 80
